ấp Giồng Giếng thuộc xã Dân Thành, TX Duyên Hải cũ; chưa có số nhà."},{"district":"Thị xã Duyên Hải","name":"Vi tính Tâm Việt - Chi nhánh Duyên Hải","address_line":"Khóm 4, phường 1 cũ, thị xã Duyên Hải (khu ngã năm vòng xoay)","category":"van_phong_pham","phone":"02946502502","tax_code":null,"source_key":"web:tx-duyen-hai-tam-viet-cn2","source_url":"https://sonca.vn/top-10-cua-hang-van-phong-pham-o-tra-vinh-uy-tin-nhat/","verification_note":"Nguồn danh bạ chủ yếu kinh doanh thiết bị tin học/máy in; cần xác minh có hàng VPP bán lẻ. Số điện thoại chung hệ thống."},{"district":"Thị xã Duyên Hải","name":"Công ty TNHH MTV Máy tính Triệu Ngân","address_line":"104 đường 2 Tháng 9, khóm 1, phường 1 cũ, thị xã Duyên Hải","category":"van_phong_pham","phone":null,"tax_code":"2100580100","source_key":"web:tx-duyen-hai-trieu-ngan-2100580100","source_url":"https://xinvoice.vn/mst/2100580100-cong-ty-tnhh-mtv-thuong-mai-dich-vu-may-tinh-trieu-ngan","verification_note":"Hồ sơ có kinh doanh sỉ VPP, thiết bị dạy học nhưng ngành chính máy tính; cần kiểm tra điểm bán và mặt hàng."},{"district":"Thị xã Duyên Hải","name":"Hộ kinh doanh TT máy vi tính - VPP An Khang","address_line":"Khóm 1, phường 1 cũ, thị xã Duyên Hải (chưa có số nhà)","category":"van_phong_pham","phone":null,"tax_code":"2100428515","source_key":"web:tx-duyen-hai-vpp-an-khang-2100428515","source_url":"https://masothue.com/Search/?q=TR%E1%BB%8ANH+TH%E1%BB%8A+NG%E1%BB%8CC+H%C3%80&type=legalName","verification_note":"Nguồn chỉ ghi tên cơ sở và địa bàn, chưa xác minh số nhà, sản phẩm/hoạt động và điện thoại."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,
 phone text,tax_code text,source_key text,source_url text,verification_note text)
), ins AS (
 INSERT INTO public.field_prospects(
 id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,
 status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT
 (substr(s.digest,1,8)||'-'||substr(s.digest,9,4)||'-5'||substr(s.digest,14,3)
 ||'-8'||substr(s.digest,18,3)||'-'||substr(s.digest,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',
 s.name,s.address_line,'Trà Vinh',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai thu thập 21/11/2026; Chưa ghé; GPS chưa xác minh. '
 ||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-tra-vinh-old-wave-03-three-districts'
 FROM src s
 WHERE s.district IN ('Huyện Trà Cú','Huyện Duyên Hải','Thị xã Duyên Hải')
  AND s.source_url LIKE 'https://%'
  AND NOT EXISTS(
   SELECT 1 FROM public.customers c WHERE c.province='Trà Vinh' AND c.district=s.district
    AND lower(btrim(c.name))=lower(btrim(s.name)))
  AND NOT EXISTS(
   SELECT 1 FROM public.field_prospects p WHERE p.province='Trà Vinh' AND p.district=s.district
    AND (p.research_source_key=s.source_key OR
     (lower(btrim(p.name))=lower(btrim(s.name)) AND lower(btrim(p.address_line))=lower(btrim(s.address_line)))))
 ON CONFLICT (research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING
 RETURNING district,name,phone,tax_code
)
SELECT district,count(*)::int AS inserted,
 count(*) FILTER(WHERE phone IS NOT NULL)::int AS phones,
 count(*) FILTER(WHERE tax_code IS NOT NULL)::int AS tax_codes
FROM ins GROUP BY district ORDER BY district;